 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"HotScatterAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.ydf.gez!=undefined){
			
			if(gameController.yrc!=parseInt(tmpMess[1])){
				
			gameController.yrc=parseInt(tmpMess[1]);	
			gameController.ydf.gez.jew("creditd", "#dsp", [gameController.jjt(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
